SELECT
	hid.hidr_nnhidrometro AS "NR HIDROMETRO",
	usu.usur_nmlogin AS "LOGIN INSTALADOR",
	(CASE 
	WHEN emp.empr_id = 1 THEN uno.unid_dssiglaunidade 
	ELSE emp.empr_nmempresa
	END) AS "EMPRESA INSTALADOR",
	his.lagu_id AS "MATRICULA IMOVEL INSTALADO",
	TO_CHAR(his.hidi_dtinstalacaohidrometro, 'DD/MM/YYYY') AS "DATA INSTALAÇÃO",
	usu2.usur_nmlogin AS "LOGIN INSTALADOR",
	(CASE 
	WHEN emp2.empr_id = 1 THEN uno2.unid_dssiglaunidade 
	ELSE emp2.empr_nmempresa
	END) AS "EMPRESA INSTALADOR",
	his.lagu_id AS "MATRICULA IMOVEL RETIRADO",
	TO_CHAR(his.hidi_dtretiradahidrometro , 'DD/MM/YYYY') AS "DATA RETIRADA HD"
FROM
	micromedicao.hidrometro_inst_hist his
	LEFT JOIN micromedicao.hidrometro hid ON hid.hidr_id = his.hidr_id
	LEFT JOIN seguranca.usuario usu ON usu.usur_id = his.usur_idinstalacao
	LEFT JOIN cadastro.unidade_organizacional uno ON uno.unid_id = usu.unid_id
	LEFT JOIN cadastro.empresa emp ON emp.empr_id = usu.empr_id
	LEFT JOIN seguranca.usuario usu2 ON usu2.usur_id = his.usur_idretirada
	LEFT JOIN cadastro.unidade_organizacional uno2 ON uno2.unid_id = usu2.unid_id
	LEFT JOIN cadastro.empresa emp2 ON emp2.empr_id = usu.empr_id
WHERE
	hid.hidr_nnhidrometro  IN ('A13B093421',
